# CyberGuard – Windows build and optional device installation.
[CmdletBinding()]
param(
    [switch]$SkipInstall = $false,
    [switch]$Clean = $false
)

$ErrorActionPreference = "Stop"
$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $ScriptDir

if (-not (Test-Path "$ScriptDir\app\build.gradle.kts")) {
    throw "Run this script from the CyberGuard project root."
}

# Prefer the project wrapper. The standard Android debug signing key is generated by
# Android Gradle Plugin when needed; no project-local debug.keystore is required.
$GradleCmd = Join-Path $ScriptDir "gradlew.bat"
if (-not (Test-Path $GradleCmd)) {
    $GradleOnPath = Get-Command gradle -ErrorAction SilentlyContinue
    if ($GradleOnPath) { $GradleCmd = "gradle" }
    else { throw "Gradle Wrapper is missing and Gradle is not available on PATH." }
}

Write-Host "[CyberGuard] Using: $GradleCmd" -ForegroundColor Cyan
java -version
if ($LASTEXITCODE -ne 0) { throw "Java is required. Install a supported JDK and configure JAVA_HOME." }

if ($Clean) {
    & $GradleCmd clean
    if ($LASTEXITCODE -ne 0) { throw "Gradle clean failed." }
}

& $GradleCmd :app:testDebugUnitTest
if ($LASTEXITCODE -ne 0) { throw "Unit tests failed." }

& $GradleCmd :app:assembleDebug
if ($LASTEXITCODE -ne 0) { throw "Debug APK build failed." }

$ApkPath = Join-Path $ScriptDir "app\build\outputs\apk\debug\app-debug.apk"
if (-not (Test-Path $ApkPath)) { throw "Build completed but APK was not found: $ApkPath" }

$ApkItem = Get-Item $ApkPath
Write-Host "[OK] Debug APK: $ApkPath ($([math]::Round($ApkItem.Length / 1MB, 2)) MB)" -ForegroundColor Green

if (-not $SkipInstall) {
    $Adb = Get-Command adb -ErrorAction SilentlyContinue
    if ($Adb) {
        $Devices = adb devices | Select-String "`tdevice$"
        if ($Devices) {
            adb install -r $ApkPath
            if ($LASTEXITCODE -ne 0) { throw "ADB installation failed." }
        } else {
            Write-Host "No connected Android device found; APK is ready for manual installation."
        }
    } else {
        Write-Host "ADB is not installed; APK is ready for manual installation."
    }
}
